import React, { useState } from "react";
import { Document, Page, pdfjs } from "react-pdf";
import "react-pdf/dist/Page/AnnotationLayer.css";
import "react-pdf/dist/Page/TextLayer.css";

// ✅ Tell react-pdf where to find the correct worker
pdfjs.GlobalWorkerOptions.workerSrc = new URL(
  "pdfjs-dist/build/pdf.worker.min.js",
  import.meta.url
).toString();

const PdfViewer = ({ file, section, onNumPages }) => {
  const [pageNumber, setPageNumber] = useState(section.start);

  const handleLoadSuccess = ({ numPages }) => {
    onNumPages(numPages);
    setPageNumber(section.start);
  };

  return (
    <div className="pdf-viewer" style={{ width: "100%", textAlign: "center" }}>
      <Document
        file={process.env.PUBLIC_URL + file}
        onLoadSuccess={handleLoadSuccess}
        loading={<p>جارٍ تحميل الملف...</p>}
        error={<p>تعذر تحميل الملف</p>}
      >
        <Page
          pageNumber={pageNumber}
          width={window.innerWidth * 0.9} // ✅ fits mobile screens
        />
      </Document>
    </div>
  );
};

export default PdfViewer;
